'use strict';

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function createArtifactHeaderController(options) {
  if (!isPlainObject(options)) throw new TypeError('options must be a plain object');
  const textFields = ['artifactId', 'artifactName', 'revision', 'ownerName', 'collectionId'];
  for (const field of textFields) {
    if (typeof options[field] !== 'string' || options[field].trim() === '') {
      throw new TypeError(field + ' must be a non-empty string');
    }
  }
  for (const field of ['editArtifact', 'deleteArtifact', 'notify']) {
    if (typeof options[field] !== 'function') throw new TypeError(field + ' must be a function');
  }

  let dialog = null;
  function getView() {
    return {
      artifactId: options.artifactId,
      artifactName: options.artifactName,
      revision: options.revision,
      ownerName: options.ownerName,
      collectionId: options.collectionId,
      backPath: '/collections/' + encodeURIComponent(options.collectionId),
      menu: ['edit', 'delete'],
      dialog
    };
  }
  function choose(action) {
    if (action !== 'edit' && action !== 'delete') throw new RangeError('unknown action');
    dialog = action;
    return dialog;
  }
  function close() {
    dialog = null;
  }
  function submit(value) {
    if (dialog === null) throw new Error('no dialog is open');
    const active = dialog;
    const result = active === 'edit'
      ? options.editArtifact(options.artifactId, value)
      : options.editArtifact(options.artifactId);
    dialog = null;
    options.notify(active === 'edit' ? 'Artifact updated' : 'Artifact deleted');
    return result;
  }
  return { getView, choose, close, submit };
}

module.exports = { createArtifactHeaderController };

