'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createArtifactHeaderController']);
const { createArtifactHeaderController } = api;

const calls = [];
const options = {
  artifactId: 'art-7', artifactName: 'Design', revision: 'r3', ownerName: 'Ada', collectionId: 'team/a',
  editArtifact(id, value) { calls.push(['edit', id, value]); return { edited: value }; },
  deleteArtifact(id) { calls.push(['delete', id]); return 'deleted-result'; },
  notify(message) { calls.push(['notify', message]); }
};
const controller = createArtifactHeaderController(options);
assert.deepStrictEqual(Object.keys(controller).sort(), ['choose', 'close', 'getView', 'submit']);
const view1 = controller.getView();
assert.deepStrictEqual(view1, {
  artifactId: 'art-7', artifactName: 'Design', revision: 'r3', ownerName: 'Ada', collectionId: 'team/a',
  backPath: '/collections/team%2Fa', menu: ['edit', 'delete'], dialog: null
});
const view2 = controller.getView();
assert.notStrictEqual(view1, view2);
assert.notStrictEqual(view1.menu, view2.menu);
view1.menu.push('other');
assert.deepStrictEqual(controller.getView().menu, ['edit', 'delete']);

assert.equal(controller.choose('edit'), 'edit');
assert.equal(controller.getView().dialog, 'edit');
const value = { name: 'Updated' };
const editResult = controller.submit(value);
assert.deepStrictEqual(editResult, { edited: value });
assert.strictEqual(calls[0][2], value);
assert.deepStrictEqual(calls, [['edit', 'art-7', value], ['notify', 'Artifact updated']]);
assert.equal(controller.getView().dialog, null);
assert.throws(() => controller.submit('unused'), Error);
assert.equal(calls.length, 2);

assert.equal(controller.choose('delete'), 'delete');
assert.equal(controller.submit('ignored'), 'deleted-result');
assert.deepStrictEqual(calls.slice(2), [['delete', 'art-7'], ['notify', 'Artifact deleted']]);
assert.equal(controller.getView().dialog, null);
assert.equal(controller.choose('edit'), 'edit');
assert.throws(() => controller.choose('rename'), RangeError);
assert.equal(controller.getView().dialog, 'edit');
assert.equal(controller.close(), undefined);
assert.equal(controller.getView().dialog, null);

let invoked = 0;
const valid = { ...options, editArtifact() { invoked++; }, deleteArtifact() { invoked++; }, notify() { invoked++; } };
const malformed = [null, [], {}, { ...valid, artifactId: '' }, { ...valid, artifactName: 1 }, { ...valid, revision: '' }, { ...valid, ownerName: null }, { ...valid, collectionId: '' }, { ...valid, editArtifact: null }, { ...valid, deleteArtifact: 'x' }, { ...valid, notify: {} }];
for (const candidate of malformed) assert.throws(() => createArtifactHeaderController(candidate), TypeError);
assert.equal(invoked, 0);

